import{_ as t,o as a,c as n,a0 as i}from"./chunks/framework.DzvPB4Y-.js";const p=JSON.parse('{"title":"1D Cutting · CSP1D","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/csp1d/index.md","filePath":"frameworks/csp1d/index.md"}'),o={name:"frameworks/csp1d/index.md"};function r(d,e,l,s,c,u){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="_1d-cutting-·-csp1d" tabindex="-1">1D Cutting · CSP1D <a class="header-anchor" href="#_1d-cutting-·-csp1d" aria-label="Permalink to &quot;1D Cutting · CSP1D&quot;">​</a></h1><p>Material has an available width and orders require products of different widths. Select cutting plans and their usage counts to satisfy demand, with configurable material, machine, production-deviation and waste rules.</p><h2 id="minimum-vocabulary" tabindex="-1">Minimum Vocabulary <a class="header-anchor" href="#minimum-vocabulary" aria-label="Permalink to &quot;Minimum Vocabulary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>API</th><th>Input or output</th></tr></thead><tbody><tr><td>Product and demand</td><td><code>Product</code> / <code>ProductDemand</code></td><td>Widths, optional length, quantity and demand mode</td></tr><tr><td>Material and machine</td><td><code>Material</code> / <code>Machine</code></td><td>Width, batches, machines and optional resource limits</td></tr><tr><td>Cutting plan</td><td><code>CuttingPlan</code></td><td>Product contribution per execution</td></tr><tr><td>Problem</td><td><code>Csp1dProblem</code></td><td>Domain data and solve configuration</td></tr><tr><td>Solving and output</td><td><code>Csp1dMilp</code> / <code>Csp1dColumnGeneration</code></td><td>Plan usage, production, demand satisfaction and enriched metrics</td></tr></tbody></table><p><strong>Variables count plan usage, not product output.</strong> Production is the sum of contributions times usage. Roll, sheet, length and weight demands are not interchangeable.</p><h2 id="entry-points" tabindex="-1">Entry Points <a class="header-anchor" href="#entry-points" aria-label="Permalink to &quot;Entry Points&quot;">​</a></h2><p>Both languages offer ordinary MILP and column generation, with different adapters, result types and configuration. Learn ordinary solving before initial plans, LP, pricing, column addition and final integer solving.</p><p>Business HTTP DTOs, tenancy, formula languages and runtime policy belong in the business adapter, not the reusable kernel.</p><h2 id="boundaries" tabindex="-1">Boundaries <a class="header-anchor" href="#boundaries" aria-label="Permalink to &quot;Boundaries&quot;">​</a></h2><ul><li>Identify product, quantity and unit together; do not collapse heterogeneous demand into a bare number.</li><li>Machine data alone does not enable every capacity constraint. Check plan resource consumption and configuration.</li><li>An insufficient initial pool may require a feasibility phase. Restricted-pool infeasibility is not full-problem infeasibility.</li><li>Heuristic or bounded pricing termination does not automatically prove integer optimality.</li></ul><h2 id="learning-path" tabindex="-1">Learning Path <a class="header-anchor" href="#learning-path" aria-label="Permalink to &quot;Learning Path&quot;">​</a></h2><ol><li>Complete <a href="./../setup.html">environment setup</a>.</li><li>Follow <a href="./first-slitting.html">your first slitting plan</a>, checking how plans contribute production.</li><li>Add overproduction bounds, shortage penalties, waste and length configuration, then consider custom pipelines.</li><li>Read <a href="/ospf/examples/framework-example3.html">framework example 3</a> and its context models for composition and column generation.</li></ol><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Reference&quot;">​</a></h2><ul><li><a href="https://github.com/fuookami/ospf-kotlin/blob/main/ospf-kotlin-framework-csp1d/README.md" target="_blank" rel="noreferrer">Kotlin API and extension contracts</a></li><li><a href="https://github.com/fuookami/ospf-rust/blob/main/ospf-rust-framework-csp1d/README.md" target="_blank" rel="noreferrer">Rust API and solving lifecycle</a></li></ul><p><a href="./../">Back to scenario selection</a></p><h2 id="continue-practicing" tabindex="-1">Continue Practicing <a class="header-anchor" href="#continue-practicing" aria-label="Permalink to &quot;Continue Practicing&quot;">​</a></h2><p>Next: <a href="./business-scenario.html">Demand Units and Business Rules</a>. Before adapting the scenario to your application, complete the <a href="./../integration.html">business integration checks</a>.</p>',17)])])}const m=t(o,[["render",r]]);export{p as __pageData,m as default};
